//! Conformance against mustache.js 4.2.0 rendering with `escape: (x) => x`, exactly as
//! the JavaScript AI SDK calls it. The fixture was generated by running mustache.js.

use serde_json::Value;
use unofficial_launchdarkly_server_sdk_ai::interpolate_template;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/mustache_js_4_2_0.json")).unwrap()
}

#[test]
fn renders_every_fixture_case_like_mustache_js() {
    let fixture = fixture();
    let view = &fixture["view"];
    let mut failures = Vec::new();
    for case in fixture["cases"].as_array().unwrap() {
        let template = case["template"].as_str().unwrap();
        let expected = case["expected"].as_str().unwrap();
        match interpolate_template(template, view) {
            Ok(actual) if actual == expected => {}
            other => failures.push(format!(
                "{template:?}: expected {expected:?}, got {other:?}"
            )),
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn rejects_the_templates_mustache_js_rejects() {
    let fixture = fixture();
    let view = &fixture["view"];
    for case in fixture["errors"].as_array().unwrap() {
        let template = case["template"].as_str().unwrap();
        let js_errors = case["error"].as_bool().unwrap();
        assert_eq!(
            interpolate_template(template, view).is_err(),
            js_errors,
            "template {template:?}"
        );
    }
}
